def compute(vars):
    intangible_assets = vars["v1"]
    trademark_license_fair_value = vars["v2"]

    if intangible_assets == 0:
        return None

    proportion = trademark_license_fair_value / intangible_assets
    percentage = proportion * 100

    return {
        "value": percentage,
        "trace": {
            "trademark_license_fair_value": trademark_license_fair_value,
            "intangible_assets": intangible_assets,
            "proportion": proportion,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
